-- LiquidityOS core schema.
-- Written for YugabyteDB YSQL (PostgreSQL-compatible). Avoids extensions;
-- UUIDs are generated by the application. Money is NUMERIC(18,2), INR.

CREATE TABLE users (
  id              UUID PRIMARY KEY,
  email           TEXT NOT NULL,
  name            TEXT NOT NULL,
  password_hash   TEXT NOT NULL,
  password_salt   TEXT NOT NULL,
  password_iters  INTEGER NOT NULL,
  legacy_id       TEXT,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted_at      TIMESTAMPTZ
);
CREATE UNIQUE INDEX users_email_uq ON users (email);
CREATE UNIQUE INDEX users_legacy_uq ON users (legacy_id);

CREATE TABLE sessions (
  id          UUID PRIMARY KEY,
  user_id     UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash  TEXT NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at  TIMESTAMPTZ NOT NULL,
  revoked_at  TIMESTAMPTZ,
  user_agent  TEXT,
  ip          TEXT
);
CREATE UNIQUE INDEX sessions_token_uq ON sessions (token_hash);
CREATE INDEX sessions_user_idx ON sessions (user_id);

CREATE TABLE families (
  id                   UUID PRIMARY KEY,
  name                 TEXT NOT NULL,
  created_by           UUID NOT NULL REFERENCES users(id),
  approval_threshold   INTEGER NOT NULL DEFAULT 1 CHECK (approval_threshold >= 1),
  created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at           TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Roles: owner > admin > member > viewer.
CREATE TABLE family_members (
  family_id   UUID NOT NULL REFERENCES families(id) ON DELETE CASCADE,
  user_id     UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role        TEXT NOT NULL CHECK (role IN ('owner','admin','member','viewer')),
  status      TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','removed')),
  joined_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (family_id, user_id)
);
CREATE INDEX family_members_user_idx ON family_members (user_id);

CREATE TABLE family_invitations (
  id           UUID PRIMARY KEY,
  family_id    UUID NOT NULL REFERENCES families(id) ON DELETE CASCADE,
  email        TEXT NOT NULL,
  role         TEXT NOT NULL CHECK (role IN ('admin','member','viewer')),
  token_hash   TEXT NOT NULL,
  invited_by   UUID NOT NULL REFERENCES users(id),
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at   TIMESTAMPTZ NOT NULL,
  accepted_at  TIMESTAMPTZ,
  revoked_at   TIMESTAMPTZ
);
CREATE UNIQUE INDEX family_invitations_token_uq ON family_invitations (token_hash);
CREATE INDEX family_invitations_email_idx ON family_invitations (email);

-- Explicit, revocable consents (data sharing, Meko context, broker sync).
CREATE TABLE consents (
  id          UUID PRIMARY KEY,
  user_id     UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  family_id   UUID REFERENCES families(id) ON DELETE CASCADE,
  scope       TEXT NOT NULL CHECK (scope IN ('meko_context','broker_sync','ai_analysis')),
  granted_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  revoked_at  TIMESTAMPTZ
);
CREATE INDEX consents_user_idx ON consents (user_id, scope);

-- Accounts and assets. 'value' is the manually-entered or synced value of the
-- whole account; brokerage/mutual-fund accounts may instead derive value from holdings.
CREATE TABLE accounts (
  id             UUID PRIMARY KEY,
  family_id      UUID NOT NULL REFERENCES families(id) ON DELETE CASCADE,
  created_by     UUID NOT NULL REFERENCES users(id),
  name           TEXT NOT NULL,
  kind           TEXT NOT NULL CHECK (kind IN (
                   'bank','cash','savings','fixed_deposit','brokerage','mutual_fund',
                   'retirement','gold','real_estate','other')),
  liquidity      TEXT NOT NULL CHECK (liquidity IN ('liquid','semi_liquid','illiquid')),
  value          NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (value >= 0),
  value_source   TEXT NOT NULL DEFAULT 'manual' CHECK (value_source IN ('manual','holdings','broker')),
  -- Share of a manually-valued account exposed to equity-market moves (e.g. an equity MF = 100).
  equity_pct     NUMERIC(5,2) NOT NULL DEFAULT 0 CHECK (equity_pct >= 0 AND equity_pct <= 100),
  visibility     TEXT NOT NULL DEFAULT 'family' CHECK (visibility IN ('private','family')),
  institution    TEXT,
  maturity_date  DATE,
  notes          TEXT,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted_at     TIMESTAMPTZ
);
CREATE INDEX accounts_family_idx ON accounts (family_id);

CREATE TABLE account_owners (
  account_id  UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  user_id     UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  share_pct   NUMERIC(5,2) NOT NULL CHECK (share_pct > 0 AND share_pct <= 100),
  PRIMARY KEY (account_id, user_id)
);
CREATE INDEX account_owners_user_idx ON account_owners (user_id);

CREATE TABLE holdings (
  id             UUID PRIMARY KEY,
  account_id     UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  symbol         TEXT NOT NULL,
  exchange       TEXT NOT NULL DEFAULT 'NSE' CHECK (exchange IN ('NSE','BSE')),
  isin           TEXT,
  name           TEXT,
  sector         TEXT,
  instrument     TEXT NOT NULL DEFAULT 'equity' CHECK (instrument IN ('equity','etf','mutual_fund','bond')),
  quantity       NUMERIC(18,4) NOT NULL CHECK (quantity >= 0),
  avg_price      NUMERIC(18,4) NOT NULL DEFAULT 0 CHECK (avg_price >= 0),
  last_price     NUMERIC(18,4),
  price_as_of    TIMESTAMPTZ,
  price_source   TEXT,
  source         TEXT NOT NULL DEFAULT 'manual' CHECK (source IN ('manual','zerodha')),
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX holdings_account_idx ON holdings (account_id);
CREATE UNIQUE INDEX holdings_account_symbol_uq ON holdings (account_id, exchange, symbol);

CREATE TABLE liabilities (
  id                 UUID PRIMARY KEY,
  family_id          UUID NOT NULL REFERENCES families(id) ON DELETE CASCADE,
  created_by         UUID NOT NULL REFERENCES users(id),
  name               TEXT NOT NULL,
  kind               TEXT NOT NULL CHECK (kind IN (
                       'home_loan','car_loan','personal_loan','education_loan',
                       'credit_card','gold_loan','business_loan','other')),
  outstanding        NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (outstanding >= 0),
  interest_rate_pct  NUMERIC(6,3) CHECK (interest_rate_pct >= 0),
  emi_monthly        NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (emi_monthly >= 0),
  remaining_months   INTEGER CHECK (remaining_months >= 0),
  rate_type          TEXT NOT NULL DEFAULT 'fixed' CHECK (rate_type IN ('fixed','floating')),
  visibility         TEXT NOT NULL DEFAULT 'family' CHECK (visibility IN ('private','family')),
  lender             TEXT,
  notes              TEXT,
  created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted_at         TIMESTAMPTZ
);
CREATE INDEX liabilities_family_idx ON liabilities (family_id);

CREATE TABLE liability_owners (
  liability_id  UUID NOT NULL REFERENCES liabilities(id) ON DELETE CASCADE,
  user_id       UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  share_pct     NUMERIC(5,2) NOT NULL CHECK (share_pct > 0 AND share_pct <= 100),
  PRIMARY KEY (liability_id, user_id)
);
CREATE INDEX liability_owners_user_idx ON liability_owners (user_id);

-- Recurring income and expenses. amount is per 'frequency' period;
-- the engine normalises to a monthly equivalent.
CREATE TABLE cashflows (
  id           UUID PRIMARY KEY,
  family_id    UUID NOT NULL REFERENCES families(id) ON DELETE CASCADE,
  created_by   UUID NOT NULL REFERENCES users(id),
  direction    TEXT NOT NULL CHECK (direction IN ('income','expense')),
  category     TEXT NOT NULL,
  name         TEXT NOT NULL,
  amount       NUMERIC(18,2) NOT NULL CHECK (amount >= 0),
  frequency    TEXT NOT NULL DEFAULT 'monthly' CHECK (frequency IN ('monthly','quarterly','half_yearly','yearly')),
  essential    BOOLEAN NOT NULL DEFAULT TRUE,
  visibility   TEXT NOT NULL DEFAULT 'family' CHECK (visibility IN ('private','family')),
  starts_on    DATE,
  ends_on      DATE,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted_at   TIMESTAMPTZ
);
CREATE INDEX cashflows_family_idx ON cashflows (family_id);

CREATE TABLE cashflow_owners (
  cashflow_id  UUID NOT NULL REFERENCES cashflows(id) ON DELETE CASCADE,
  user_id      UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  share_pct    NUMERIC(5,2) NOT NULL CHECK (share_pct > 0 AND share_pct <= 100),
  PRIMARY KEY (cashflow_id, user_id)
);
CREATE INDEX cashflow_owners_user_idx ON cashflow_owners (user_id);

CREATE TABLE transactions (
  id           UUID PRIMARY KEY,
  account_id   UUID NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,
  created_by   UUID NOT NULL REFERENCES users(id),
  occurred_on  DATE NOT NULL,
  amount       NUMERIC(18,2) NOT NULL,          -- positive = inflow, negative = outflow
  category     TEXT,
  description  TEXT,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX transactions_account_idx ON transactions (account_id, occurred_on);

-- Saved simulation runs (inputs and deterministic outputs).
CREATE TABLE simulations (
  id           UUID PRIMARY KEY,
  family_id    UUID NOT NULL REFERENCES families(id) ON DELETE CASCADE,
  created_by   UUID NOT NULL REFERENCES users(id),
  scope        TEXT NOT NULL CHECK (scope IN ('family','individual')),
  scope_user   UUID REFERENCES users(id),
  kind         TEXT NOT NULL,
  name         TEXT,
  input        JSONB NOT NULL,
  output       JSONB NOT NULL,
  engine_ver   TEXT NOT NULL,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX simulations_family_idx ON simulations (family_id, created_at);

-- Resilience score history, used to explain why a score changed.
CREATE TABLE score_snapshots (
  id           UUID PRIMARY KEY,
  family_id    UUID NOT NULL REFERENCES families(id) ON DELETE CASCADE,
  scope        TEXT NOT NULL CHECK (scope IN ('family','individual')),
  scope_user   UUID REFERENCES users(id) ON DELETE CASCADE,
  viewer_id    UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  score        NUMERIC(5,1) NOT NULL,
  report       JSONB NOT NULL,
  engine_ver   TEXT NOT NULL,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX score_snapshots_lookup_idx ON score_snapshots (family_id, viewer_id, scope, created_at);

CREATE TABLE proposals (
  id               UUID PRIMARY KEY,
  family_id        UUID NOT NULL REFERENCES families(id) ON DELETE CASCADE,
  created_by       UUID NOT NULL REFERENCES users(id),
  kind             TEXT NOT NULL CHECK (kind IN ('buy_stock','sell_stock','purchase','loan','other')),
  title            TEXT NOT NULL,
  description      TEXT,
  amount           NUMERIC(18,2),
  payload          JSONB NOT NULL DEFAULT '{}'::jsonb,
  impact           JSONB,
  status           TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','approved','rejected','withdrawn')),
  required_approvals INTEGER NOT NULL DEFAULT 1,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  decided_at       TIMESTAMPTZ
);
CREATE INDEX proposals_family_idx ON proposals (family_id, created_at);

CREATE TABLE proposal_votes (
  proposal_id  UUID NOT NULL REFERENCES proposals(id) ON DELETE CASCADE,
  user_id      UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  vote         TEXT NOT NULL CHECK (vote IN ('approve','reject')),
  note         TEXT,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (proposal_id, user_id)
);

CREATE TABLE proposal_comments (
  id           UUID PRIMARY KEY,
  proposal_id  UUID NOT NULL REFERENCES proposals(id) ON DELETE CASCADE,
  user_id      UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  body         TEXT NOT NULL,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX proposal_comments_idx ON proposal_comments (proposal_id, created_at);

-- Per-user broker connections. Access tokens are AES-256-GCM encrypted by the app.
CREATE TABLE broker_connections (
  id                UUID PRIMARY KEY,
  user_id           UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  broker            TEXT NOT NULL CHECK (broker IN ('zerodha')),
  broker_user_id    TEXT NOT NULL,
  broker_user_name  TEXT,
  access_token_enc  TEXT NOT NULL,
  connected_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at        TIMESTAMPTZ NOT NULL,
  last_synced_at    TIMESTAMPTZ,
  revoked_at        TIMESTAMPTZ
);
CREATE INDEX broker_connections_user_idx ON broker_connections (user_id, broker);

-- One pending OAuth state per login attempt, so callbacks map to the right user.
CREATE TABLE oauth_states (
  state       TEXT PRIMARY KEY,
  user_id     UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  family_id   UUID REFERENCES families(id) ON DELETE CASCADE,
  provider    TEXT NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at  TIMESTAMPTZ NOT NULL
);

CREATE TABLE concall_analyses (
  id          UUID PRIMARY KEY,
  user_id     UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  family_id   UUID REFERENCES families(id) ON DELETE CASCADE,
  ticker      TEXT NOT NULL,
  company     TEXT NOT NULL,
  quarter     TEXT NOT NULL,
  fiscal_year TEXT NOT NULL,
  source      TEXT,
  source_url  TEXT,
  analysis    JSONB NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX concall_analyses_user_idx ON concall_analyses (user_id, created_at);
CREATE INDEX concall_analyses_ticker_idx ON concall_analyses (ticker, created_at);

-- Subscription entitlements (no payment gateway yet).
CREATE TABLE subscriptions (
  user_id             UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  plan                TEXT NOT NULL DEFAULT 'free' CHECK (plan IN ('free','premium')),
  status              TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','cancelled','expired')),
  current_period_end  TIMESTAMPTZ,
  updated_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE usage_counters (
  user_id   UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  feature   TEXT NOT NULL,
  period    TEXT NOT NULL,                     -- e.g. '2026-10'
  count     INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (user_id, feature, period)
);

CREATE TABLE audit_log (
  id           UUID PRIMARY KEY,
  family_id    UUID,
  actor_id     UUID,
  action       TEXT NOT NULL,
  entity_type  TEXT,
  entity_id    TEXT,
  details      JSONB,
  ip           TEXT,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX audit_log_family_idx ON audit_log (family_id, created_at);
CREATE INDEX audit_log_actor_idx ON audit_log (actor_id, created_at);
